const express = require('express');
const crypto = require('crypto');
const { URL } = require('url');

// Secure session store with HMAC verification
const sessions = new Map();
const HMAC_SECRET = crypto.randomBytes(32);

function createHmac(data) {
  return crypto.createHmac('sha256', HMAC_SECRET).update(data).digest('hex');
}

// Role-based access control configuration
const ROLE_HIERARCHY = { admin: 3, editor: 2, viewer: 1 };
const PROTECTED_PATHS = [
  { pattern: '/admin', minRole: 'admin' },
  { pattern: '/api/users', minRole: 'editor' },
  { pattern: '/api/content', minRole: 'viewer' }
];

// User database with bcrypt-hashed passwords (simulated)
const users = new Map([
  ['admin', { passwordHash: '$2b$12$LJ3m4sMKfXzSGOFCxyNIcOBbIbCFw.RJKc5g8rLQ5JvHnZpYvKYGi', role: 'admin' }],
  ['editor1', { passwordHash: '$2b$12$9Xn7sWzGEbXgKBRSyZ8YXeJFHdCvRqM5N3kA7LpQwE2TjVhYmNOuS', role: 'editor' }],
  ['viewer1', { passwordHash: '$2b$12$kP8mNvBcXwYzR3tA5sD7fOhJgKlMnQpWxE2vU4iY6oC8aS0dF1gHj', role: 'viewer' }]
]);

const app = express();
app.use(express.json());

// Path normalization to prevent traversal
function normalizePath(inputPath) {
  // Decode percent-encoding
  let decoded = decodeURIComponent(inputPath);
  // Remove null bytes
  decoded = decoded.replace(/\x00/g, '');
  // Collapse multiple slashes
  decoded = decoded.replace(/\/+/g, '/');
  // Remove trailing slash
  decoded = decoded.replace(/\/$/, '') || '/';
  return decoded;
}

// Authorization check - validates path against role requirements
function isAuthorized(userRole, requestPath) {
  const normalizedPath = normalizePath(requestPath);

  for (const route of PROTECTED_PATHS) {
    // Check if the normalized path starts with the protected pattern
    if (normalizedPath.startsWith(route.pattern)) {
      const userLevel = ROLE_HIERARCHY[userRole] || 0;
      const requiredLevel = ROLE_HIERARCHY[route.minRole] || 999;
      return userLevel >= requiredLevel;
    }
  }
  // Unprotected path - allow access
  return true;
}

// Session validation middleware
function authenticateSession(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  const sessionHmac = req.headers['x-session-hmac'];

  if (!sessionId || !sessionHmac) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Verify HMAC to prevent session tampering
  const expectedHmac = createHmac(sessionId);
  if (!crypto.timingSafeEqual(Buffer.from(expectedHmac, 'hex'), Buffer.from(sessionHmac, 'hex'))) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  const session = sessions.get(sessionId);
  if (!session || session.expiresAt < Date.now()) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: 'Session expired' });
  }

  req.user = session.user;
  next();
}

// Authorization middleware
function authorizeRequest(req, res, next) {
  const requestPath = req.path;

  if (!isAuthorized(req.user.role, requestPath)) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  next();
}

// Login endpoint
app.post('/auth/login', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  const user = users.get(username);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // In production, use bcrypt.compare(password, user.passwordHash)
  // Simulated for this example
  const sessionId = crypto.randomUUID();
  const hmac = createHmac(sessionId);

  sessions.set(sessionId, {
    user: { username, role: user.role },
    expiresAt: Date.now() + 3600000
  });

  res.json({ sessionId, hmac, expiresIn: 3600 });
});

// Admin panel - requires admin role
app.get('/admin/*', authenticateSession, authorizeRequest, (req, res) => {
  res.json({ message: 'Admin panel', data: { users: Array.from(users.keys()) } });
});

// User management API - requires editor role  
app.get('/api/users/*', authenticateSession, authorizeRequest, (req, res) => {
  res.json({ message: 'User list', data: Array.from(users.entries()).map(([k, v]) => ({ username: k, role: v.role })) });
});

// Content API - requires viewer role
app.get('/api/content/*', authenticateSession, authorizeRequest, (req, res) => {
  res.json({ message: 'Content', data: [] });
});

// File serving endpoint with path validation
app.get('/files/:filename', authenticateSession, (req, res) => {
  const filename = req.params.filename;

  // Validate filename - allow only alphanumeric, dash, underscore, dot
  // Uses Unicode-aware regex
  const safePattern = /^[\w.\-]+$/u;
  if (!safePattern.test(filename)) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  // Construct path and serve
  const filePath = `/var/app/files/${filename}`;
  res.json({ serving: filePath });
});

module.exports = app;
